test_v1_zustand_aller_slots_verglichen[p22_basis_slot-class Basis:
 __slots__ = ('stand',)

 def __init__(self, stand: int):
 self.stand = stand


class Konto(Basis):
 __slots__ = ('name',)

 def __init__(self, stand: int):
 super().__init__(stand)
 self.name = 'k'

 def buchen(self, b: int) -> None:
 self.stand += b
